package web

import (
	"html/template"
	"time"
)

var pages = template.Must(template.New("pages").Funcs(template.FuncMap{
	"short": func(s string) string {
		if len(s) > 12 {
			return s[:12]
		}
		return s
	},
	// when renders a stored RFC 3339 timestamp as a readable UTC time inside a
	// <time> element; app.js converts it to the viewer's local time. Only
	// formatted digits are interpolated, so the HTML is safe.
	"when": func(ts string) template.HTML {
		t, err := time.Parse(time.RFC3339Nano, ts)
		if err != nil {
			return "—"
		}
		t = t.UTC()
		return template.HTML(`<time datetime="` + t.Format(time.RFC3339) + `">` + t.Format("2006-01-02 15:04 UTC") + `</time>`)
	},
	// field renders the id and, for the field named in a validation error, the
	// accessibility attributes that highlight and focus it. Names are template
	// constants, never user input.
	"field": func(errorField, name string) template.HTMLAttr {
		attrs := `id="f-` + name + `"`
		if errorField == name {
			attrs += ` aria-invalid="true" aria-describedby="form-error" autofocus`
		}
		return template.HTMLAttr(attrs)
	},
	"elapsed": func(start, end string) string {
		a, err := time.Parse(time.RFC3339Nano, start)
		if err != nil {
			return "—"
		}
		b := time.Now()
		if end != "" {
			b, _ = time.Parse(time.RFC3339Nano, end)
		}
		return b.Sub(a).Round(time.Second).String()
	},
}).Parse(`<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>RepoDeploy</title><link rel="stylesheet" href="/static/app.css"><script src="/static/app.js" defer></script></head><body{{if .Refresh}} data-refresh="1"{{end}}>
<header><a href="/" class="brand">RepoDeploy</a>{{if .CSRF}}<nav class="actions"><a href="/settings">Security</a><form method="post" action="/logout"><input type="hidden" name="_csrf" value="{{.CSRF}}"><button class="secondary">Sign out</button></form></nav>{{end}}</header>
{{if .ConnectionView}}{{template "connections" .}}{{end}}
{{if eq .View "login"}}<section class="narrow"><h1>Sign in</h1>{{if .Notice}}<p class="success" role="status">{{.Notice}}</p>{{end}}{{if .Error}}<p class="notice" role="alert">{{.Error}}</p>{{end}}<form method="post" action="/login"><label for="password">Administrator password</label><input id="password" name="password" type="password" autocomplete="current-password" required><button>Sign in</button></form></section>{{end}}
{{if eq .View "home"}}<h1>Projects</h1>{{if .Notice}}<p class="success" role="status">{{.Notice}}</p>{{end}}<p class="muted">Deploy Git commits on this host.</p><p><a href="/connections">Connect GitHub, Bitbucket or SSH</a></p><div class="grid">{{range .Projects}}{{$j := index $.Latest .ID}}<div class="card"><h2><a href="/projects/{{.ID}}">{{.Name}}</a></h2>{{if $j.ID}}<p><a href="/jobs/{{$j.ID}}" class="status {{if eq $j.Phase "succeeded"}}ok{{else if eq $j.Phase "failed"}}failed{{else}}running{{end}}">{{template "phase" $j.Phase}}</a></p><p><small>{{if $j.Commit}}<code>{{short $j.Commit}}</code> · {{end}}{{if $j.Finished}}{{when $j.Finished}}{{else}}{{when $j.Created}}{{end}}</small></p>{{else}}<p class="muted">Never deployed</p>{{end}}<p>{{.Branch}} · {{.Mode}}</p>{{if .Blocked}}<p class="notice">Recovery failed · blocked</p>{{else if .Paused}}<p class="notice">Automation paused</p>{{end}}{{if .PollError}}<p class="notice">Polling failing</p>{{end}}<small>{{if .Active}}Active release {{short .Active}}{{else}}No active release{{end}}</small></div>{{else}}<p>No projects yet. Connect a repository below.</p>{{end}}</div><details {{if not .Projects}}open{{end}}><summary>Advanced: Git URL and existing SSH files</summary>{{template "projectForm" .}}</details>{{end}}
{{define "phase"}}{{if eq . "succeeded"}}✓ Deployed{{else if eq . "failed"}}✗ Failed{{else if eq . "waiting_ci"}}Waiting for CI/CD{{else if eq . "queued"}}Queued{{else}}In progress · {{.}}{{end}}{{end}}
{{if eq .View "project"}}<p><a href="/">Projects</a> / {{.Project.Name}}</p><h1>{{.Project.Name}}</h1><p>{{.Project.Repo}} · <strong>{{.Project.Branch}}</strong></p>
{{if .Project.Blocked}}<p class="notice">Recovery failed. Restore a retained healthy release before resuming automation. Inspect deployment logs and the host.</p>{{else if .Project.Paused}}<p class="notice">Automation is paused after rollback.</p>{{end}}{{if .Project.PollError}}<p class="notice">{{.Project.PollError}}</p>{{end}}
<div class="actions"><form method="post" action="/projects/{{.Project.ID}}/deploy"><input type="hidden" name="_csrf" value="{{.CSRF}}"><button data-confirm="Deploy the current head of {{.Project.Branch}} now?">Deploy branch</button></form>{{if .Project.Paused}}<form method="post" action="/projects/{{.Project.ID}}/resume"><input type="hidden" name="_csrf" value="{{.CSRF}}"><button class="secondary">Resume automation</button></form>{{end}}</div>
<section><h2>Deployment history</h2><div class="scroll"><table><thead><tr><th>Commit</th><th>Created</th><th>Duration</th><th>State</th><th>Action</th></tr></thead><tbody>{{range .Jobs}}<tr><td><a href="/jobs/{{.ID}}">{{if .Commit}}{{short .Commit}}{{else}}Pending{{end}}</a>{{if eq $.Project.Active .ID}} · active{{end}}</td><td>{{when .Created}}</td><td>{{elapsed .Started .Finished}}</td><td>{{.Phase}}{{if .Recovery}} · recovery {{.Recovery}}{{end}}</td><td>{{if eq .Phase "succeeded"}}<form method="post" action="/projects/{{$.Project.ID}}/rollback"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><input type="hidden" name="release_id" value="{{.ID}}"><button class="secondary">Restore</button></form>{{end}}</td></tr>{{else}}<tr><td colspan="5">No deployments yet.</td></tr>{{end}}</tbody></table></div></section>
<section id="secrets"><h2>Secrets and configs</h2><p class="muted">Values for Compose <code>secrets</code>/<code>configs</code> declared with <code>external: true</code>. Values are never displayed. Changes apply from the next deployment; retained releases keep the values they were deployed with.</p>{{if .SecretError}}<p class="notice" role="alert">{{.SecretError}}</p>{{end}}{{if .Secrets}}<div class="scroll"><table><thead><tr><th>Name</th><th>Value</th><th>Active release</th><th>Action</th></tr></thead><tbody>{{range .Secrets}}<tr><td><code>{{.Name}}</code></td><td>{{if .Stored}}Stored · {{.Size}} bytes · {{when .Modified}}{{else}}<strong>Missing</strong>{{end}}</td><td>{{if .Required}}Required{{else}}<span class="muted">Not used</span>{{end}}</td><td>{{if .Stored}}<form method="post" action="/projects/{{$.Project.ID}}/secrets/{{.Name}}/delete"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><button class="secondary" data-confirm="Delete the stored value of {{.Name}}? The next deployment fails if the Compose file still needs it.">Delete</button></form>{{end}}</td></tr>{{end}}</tbody></table></div>{{else}}<p>No secrets stored.</p>{{end}}
<form method="post" action="/projects/{{.Project.ID}}/secrets" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="{{.CSRF}}"><div class="grid"><label>Name<input name="name" required maxlength="100" pattern="[A-Za-z0-9_\-]+" placeholder="app_password" autocomplete="off"></label><label>Upload a file (optional)<input name="file" type="file"></label></div><label>Or paste the value<textarea name="value" rows="4" autocomplete="off" spellcheck="false"></textarea></label><button>Save secret</button> <small>Saving an existing name replaces its value. Maximum about 1 MB.</small></form></section>
<details><summary>Project settings</summary>{{template "projectForm" .}}</details><details><summary>GitHub webhook</summary><p>Configure an HTTPS endpoint at <code>/hooks/github/{{.Project.ID}}</code>, JSON content type and push events only. Keep SSL verification enabled.</p><form method="post" action="/projects/{{.Project.ID}}/webhook-secret"><input type="hidden" name="_csrf" value="{{.CSRF}}"><button class="secondary">Generate / rotate webhook secret</button></form><p><small>Rotating invalidates the previous secret immediately.</small></p></details><details class="danger"><summary>Delete project</summary><p>Stops the application, removes its containers, built images, release history, logs and stored secrets.</p><p><a href="/projects/{{.Project.ID}}/delete">Continue to deletion</a></p></details>{{end}}
{{if eq .View "delete"}}<p><a href="/">Projects</a> / <a href="/projects/{{.Project.ID}}">{{.Project.Name}}</a></p><h1>Delete {{.Project.Name}}?</h1><section class="danger">{{if .Error}}<p class="notice" role="alert">{{.Error}}</p>{{end}}<p>This stops the running application and permanently removes its containers, built images, release history, logs, stored secrets and webhook secret. Provider authorizations and generated SSH keys are kept.</p><form method="post" action="/projects/{{.Project.ID}}/delete"><input type="hidden" name="_csrf" value="{{.CSRF}}"><label class="inline"><input type="checkbox" name="volumes"> Also delete the named volumes (application data). This cannot be undone.</label><p></p><label for="confirm_name">Type <code>{{.Project.Name}}</code> to confirm</label><input id="confirm_name" name="confirm_name" autocomplete="off" required><div class="actions"><button class="danger">Delete project</button><a class="button-link" href="/projects/{{.Project.ID}}">Cancel</a></div></form></section>{{end}}
{{if eq .View "secret"}}<section><h1>Webhook secret</h1><p>Copy this into GitHub's webhook settings. It is only displayed in this response.</p><code>{{.Secret}}</code><p><a href="/projects/{{.Project.ID}}">Back to project</a></p></section>{{end}}
{{if eq .View "job"}}<p><a href="/projects/{{.Job.ProjectID}}">{{.Job.Project.Name}}</a> / Deployment</p><h1>Deployment {{short .Job.ID}}</h1><p>Commit <code>{{.Job.Commit}}</code></p><p>State: <strong id="phase">{{.Job.Phase}}</strong> · Recovery: {{.Job.Recovery}} · {{elapsed .Job.Started .Job.Finished}}</p>{{if .Job.Error}}<p class="notice">{{.Job.Error}}</p>{{end}}<pre id="logs" aria-label="Deployment logs" data-log-stream="/api/jobs/{{.Job.ID}}/logs?follow=1"{{if or (eq .Job.Phase "succeeded") (eq .Job.Phase "failed")}} data-final="1"{{end}}></pre><noscript><pre>{{.Logs}}</pre></noscript><p><small>Logs are capped at 1 MiB per deployment. Restoring an image does not undo database migrations.</small></p>{{end}}
{{if eq .View "settings"}}<p><a href="/">Projects</a> / Security</p><h1>Security</h1>{{if .Error}}<p class="notice" role="alert">{{.Error}}</p>{{end}}
<section><h2>Change administrator password</h2><p class="muted">Changing the password signs out every browser session, including this one. The CLI token is not affected.</p><form method="post" action="/settings/password"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="text" name="username" value="admin" autocomplete="username" hidden><label for="current_password">Current password</label><input id="current_password" name="current_password" type="password" autocomplete="current-password" required><label for="new_password">New password (at least 12 characters)</label><input id="new_password" name="new_password" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required><label for="confirm_password">Repeat new password</label><input id="confirm_password" name="confirm_password" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required><button>Change password</button></form></section>
<section><h2>CLI token</h2><p class="muted">Rotating issues a new token, stores it in <code>admin.token</code> in the state directory and immediately revokes the previous one. Remote CLI machines must receive the new token.</p><form method="post" action="/settings/token"><input type="hidden" name="_csrf" value="{{.CSRF}}"><button class="secondary">Rotate CLI token</button></form></section>{{end}}
{{if eq .View "token"}}<section><h1>New CLI token</h1><p>The previous token no longer works. Local commands read the new value from <code>admin.token</code> automatically. For remote machines, copy it now: it is only displayed in this response.</p><code>{{.Secret}}</code><p><a href="/settings">Back to security</a></p></section>{{end}}
{{define "projectForm"}}<form method="post" action="/projects{{if .Project.ID}}/{{.Project.ID}}{{end}}" class="project-form"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="connection" value="{{.Project.Connection}}"><input type="hidden" name="repository_id" value="{{.Project.RepositoryID}}">{{if .SSH.ID}}<input type="hidden" name="ssh_key_id" value="{{.SSH.ID}}">{{end}}{{if .Wizard}}<input type="hidden" name="deploy" value="1">{{end}}
{{if .FormError}}<p class="notice" role="alert" id="form-error">{{.FormError}}{{if .ErrorField}} <a href="#f-{{.ErrorField}}">Go to the field</a>{{end}}</p>{{end}}
<fieldset><legend>Source and automation</legend><div class="grid">
<label>Name<input {{field .ErrorField "name"}} name="name" value="{{.Project.Name}}" required maxlength="100"></label>{{if .Wizard}}<label>Repository<code>{{.Project.Repo}}</code><input type="hidden" name="repo" value="{{.Project.Repo}}"></label>{{else}}<label>Git URL<input {{field .ErrorField "repo"}} name="repo" value="{{.Project.Repo}}" placeholder="https://github.com/team/app.git" required></label>{{end}}
<label>Branch{{if .Branches}}<select {{field .ErrorField "branch"}} name="branch">{{range .Branches}}<option value="{{.}}" {{if eq . $.Project.Branch}}selected{{end}}>{{.}}</option>{{end}}</select>{{else}}<input {{field .ErrorField "branch"}} name="branch" value="{{.Project.Branch}}" required>{{end}}</label>
<label>Detection<select {{field .ErrorField "mode"}} name="mode"><option value="manual" {{if eq .Project.Mode "manual"}}selected{{end}}>Manual</option><option value="poll" {{if eq .Project.Mode "poll"}}selected{{end}}>Polling</option>{{if ne .Provider "bitbucket"}}<option value="webhook" {{if eq .Project.Mode "webhook"}}selected{{end}}>GitHub webhook</option><option value="both" {{if eq .Project.Mode "both"}}selected{{end}}>Webhook + polling reconciliation</option>{{end}}</select></label>
<label>Polling interval (seconds)<input {{field .ErrorField "poll_seconds"}} name="poll_seconds" type="number" value="{{if .Project.PollSeconds}}{{.Project.PollSeconds}}{{else}}60{{end}}" min="10" max="86400"></label>
<label>CI/CD<select {{field .ErrorField "wait_ci"}} name="wait_ci"><option value="" {{if not .Project.WaitCI}}selected{{end}}>Deploy immediately</option><option value="on" {{if .Project.WaitCI}}selected{{end}}>Wait for CI/CD</option></select></label><label>CI/CD timeout (seconds)<input {{field .ErrorField "ci_timeout"}} name="ci_timeout" type="number" value="{{if .Project.CITimeout}}{{.Project.CITimeout}}{{else}}1800{{end}}" min="30" max="86400"></label>
</div><p><small>Waiting for private CI/CD requires browser authorization for the repository provider, including when Git uses SSH.</small></p></fieldset>
<fieldset><legend>Build and health</legend><div class="choice"><label class="inline"><input type="radio" {{field .ErrorField "build_type"}} name="build_type" value="dockerfile" {{if not .Project.ComposeFile}}checked{{end}}> Dockerfile</label><label class="inline"><input type="radio" name="build_type" value="compose" {{if .Project.ComposeFile}}checked{{end}}> Docker Compose</label></div>
<div class="grid build-dockerfile">
<label>Dockerfile path<input {{field .ErrorField "dockerfile"}} name="dockerfile" value="{{or .Project.Dockerfile "Dockerfile"}}"></label>
<label>Host port<input {{field .ErrorField "port"}} name="port" type="number" value="{{if .Project.Port}}{{.Project.Port}}{{else}}8080{{end}}" min="1" max="65535"></label>
<label>Container port<input {{field .ErrorField "container_port"}} name="container_port" type="number" value="{{if .Project.ContainerPort}}{{.Project.ContainerPort}}{{else}}8080{{end}}" min="1" max="65535"></label>
{{$bind := or .Project.BindAddress "127.0.0.1"}}<label>Publish port on<select {{field .ErrorField "bind_address"}} name="bind_address"><option value="127.0.0.1" {{if eq $bind "127.0.0.1"}}selected{{end}}>127.0.0.1 · this host only (recommended)</option><option value="0.0.0.0" {{if eq $bind "0.0.0.0"}}selected{{end}}>0.0.0.0 · all interfaces</option><option value="::1" {{if eq $bind "::1"}}selected{{end}}>::1 · this host only (IPv6)</option><option value="::" {{if eq $bind "::"}}selected{{end}}>:: · all interfaces (IPv6)</option>{{if not (eq $bind "127.0.0.1" "0.0.0.0" "::1" "::")}}<option value="{{$bind}}" selected>{{$bind}}</option>{{end}}</select></label>
<label>HTTP health URL<input {{field .ErrorField "health_url"}} name="health_url" value="{{if .Project.HealthURL}}{{.Project.HealthURL}}{{else}}http://127.0.0.1:8080/health{{end}}" placeholder="http://127.0.0.1:8080/health"></label>
</div>
<div class="grid build-compose">
<label>Compose path<input {{field .ErrorField "compose_file"}} name="compose_file" value="{{or .Project.ComposeFile "compose.yaml"}}"></label>
<label>Health service<input {{field .ErrorField "health_service"}} name="health_service" value="{{.Project.HealthService}}" placeholder="app"></label>
<label>HTTP health URL (optional)<input {{field .ErrorField "compose_health_url"}} name="compose_health_url" value="{{if .Project.ComposeFile}}{{.Project.HealthURL}}{{end}}" placeholder="http://127.0.0.1:18080/health"></label>
</div>
<div class="grid">
<label>Health timeout (seconds)<input {{field .ErrorField "health_timeout"}} name="health_timeout" type="number" value="{{if .Project.HealthTimeout}}{{.Project.HealthTimeout}}{{else}}60{{end}}" min="1" max="300"></label>
<label>Versions to retain<input {{field .ErrorField "retain"}} name="retain" type="number" value="{{if .Project.Retain}}{{.Project.Retain}}{{else}}5{{end}}" min="1" max="50"></label>
<label>Privilege escalation in containers<select name="privilege_escalation"><option value="" {{if not .Project.AllowPrivilegeEscalation}}selected{{end}}>Blocked with no-new-privileges (recommended)</option><option value="allow" {{if .Project.AllowPrivilegeEscalation}}selected{{end}}>Allowed (needed for setuid tools such as sudo)</option></select></label>
<label>Image updates<select name="pull_images"><option value="" {{if not .Project.PullImages}}selected{{end}}>Reuse images already on this host</option><option value="on" {{if .Project.PullImages}}selected{{end}}>Pull newer images on every deployment</option></select></label>
</div><p><small>Dockerfile mode needs an HTTP health URL on a loopback address. Compose mode needs a service with a Docker healthcheck, an HTTP health URL, or both.</small></p></fieldset>
{{if .Wizard}}<input type="hidden" name="ssh_key" value="{{.Project.SSHKey}}"><input type="hidden" name="known_hosts" value="{{.Project.KnownHosts}}">{{else}}<fieldset><legend>Existing SSH files (optional)</legend><div class="grid"><label>SSH private key path<input {{field .ErrorField "ssh_key"}} name="ssh_key" value="{{.Project.SSHKey}}" placeholder="/var/lib/repodeploy/keys/app"></label><label>SSH known_hosts path<input {{field .ErrorField "known_hosts"}} name="known_hosts" value="{{.Project.KnownHosts}}" placeholder="/var/lib/repodeploy/keys/known_hosts"></label></div></fieldset>{{end}}
<button>{{if .Wizard}}Save and deploy{{else}}Save project{{end}}</button></form>{{end}}
{{if eq .View "edit"}}<p><a href="/">Projects</a>{{if .Project.ID}} / <a href="/projects/{{.Project.ID}}">Project</a>{{end}}</p><h1>{{if .Project.ID}}Review project settings{{else}}Review new project{{end}}</h1><section>{{template "projectForm" .}}</section>{{end}}
{{if eq .View "confirm-rollback"}}<p><a href="/">Projects</a> / <a href="/projects/{{.Project.ID}}">{{.Project.Name}}</a></p><h1>Restore release {{short .Job.ID}}?</h1><section><p>Commit <code>{{.Job.Commit}}</code>, deployed {{when .Job.Finished}}.</p><ul><li>Automatic deployments for this project are <strong>paused</strong> until you resume them.</li><li>Database migrations and data written since that release are <strong>not</strong> undone.</li><li>The secrets and configs captured with that release are restored, even if you rotated them since.</li></ul><div class="actions"><form method="post" action="/projects/{{.Project.ID}}/rollback"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="release_id" value="{{.Job.ID}}"><input type="hidden" name="confirm" value="1"><button>Restore this release</button></form><a class="button-link" href="/projects/{{.Project.ID}}">Cancel</a></div></section>{{end}}
</body></html>`))
